import React, { useState, useRef } from 'react'
import axios from 'axios'
import { useTheme } from "../component/ThemeContext"

export default function AiText() {
  const { theme } = useTheme()
  const isDark = theme === "dark"

  const [file, setFile] = useState(null)
  const [chat, setChat] = useState([]) // { type: 'user'|'ai', content: string }
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const fileInputRef = useRef(null)

  const handleFileChange = (e) => {
    setFile(e.target.files[0])
    setError('')
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!file) {
      setError('Please select a file.')
      return
    }
    const userMsg = { type: 'user', content: file.name }
    setChat((prev) => [...prev, userMsg])
    setLoading(true)
    setError('')
    try {
      const formData = new FormData()
      formData.append('file', file)
      const res = await axios.post(
        'http://localhost:5000/api/summarize',
        formData,
        { headers: { 'Content-Type': 'multipart/form-data' } }
      )
      setChat((prev) => [
        ...prev,
        { type: 'ai', content: res.data.summary || 'No summary returned.' }
      ])
    } catch (err) {
      setChat((prev) => [
        ...prev,
        { type: 'ai', content: 'Failed to get summary. Please try again.' }
      ])
    } finally {
      setLoading(false)
      setFile(null)
      if (fileInputRef.current) fileInputRef.current.value = ''
    }
  }

  return (
    <div
      style={{
        maxWidth: 480,
        margin: '0 auto',
        background: isDark ? '#0f172a' : '#f9fafb',
        borderRadius: 12,
        boxShadow: '0 2px 12px #0001',
        padding: 24,
        minHeight: 500,
        display: 'flex',
        flexDirection: 'column',
        color: isDark ? '#f7f9fc' : '#222',
        transition: 'background 0.25s ease, color 0.25s ease'
      }}
    >
      <h4 style={{
        textAlign: 'center',
        marginBottom: 24,
        color: isDark ? '#f7f9fc' : '#222'
      }}>
        AI File Summarizer
      </h4>
      <div
        style={{
          flex: 1,
          overflowY: 'auto',
          marginBottom: 16,
          padding: 8,
          background: isDark ? '#0b1320' : '#fff',
          borderRadius: 8,
          border: isDark ? '1px solid #222a' : '1px solid #eee',
          minHeight: 300,
          transition: 'background 0.25s ease, color 0.25s ease'
        }}
      >
        {chat.length === 0 && (
          <div style={{ color: isDark ? '#94a3b8' : '#888', textAlign: 'center', marginTop: 80 }}>
            Upload a file to start the conversation.
          </div>
        )}
        {chat.map((msg, idx) => (
          <div
            key={idx}
            style={{
              display: 'flex',
              justifyContent: msg.type === 'user' ? 'flex-end' : 'flex-start',
              marginBottom: 12
            }}
          >
            <div
              style={{
                maxWidth: '75%',
                padding: '10px 16px',
                borderRadius: 16,
                background: msg.type === 'user'
                  ? (isDark ? '#2563eb' : '#2563eb')
                  : (isDark ? '#1e293b' : '#f1f5f9'),
                color: msg.type === 'user'
                  ? '#fff'
                  : (isDark ? '#f7f9fc' : '#222'),
                fontSize: 15,
                whiteSpace: 'pre-wrap',
                wordBreak: 'break-word',
                boxShadow: msg.type === 'user'
                  ? '0 1px 4px #2563eb22'
                  : '0 1px 4px #0001',
                border: msg.type === 'ai' && isDark ? '1px solid #334155' : undefined,
                transition: 'background 0.25s ease, color 0.25s ease'
              }}
            >
              {msg.type === 'user' ? (
                <>
                  <span role="img" aria-label="file">📄</span> {msg.content}
                </>
              ) : (
                msg.content
              )}
            </div>
          </div>
        ))}
        {loading && (
          <div style={{ display: 'flex', justifyContent: 'flex-start', marginBottom: 12 }}>
            <div
              style={{
                maxWidth: '75%',
                padding: '10px 16px',
                borderRadius: 16,
                background: isDark ? '#1e293b' : '#f1f5f9',
                color: isDark ? '#f7f9fc' : '#222',
                fontSize: 15,
                transition: 'background 0.25s ease, color 0.25s ease'
              }}
            >
              <span>Summarizing...</span>
            </div>
          </div>
        )}
      </div>
      <form
        onSubmit={handleSubmit}
        style={{ display: 'flex', gap: 8, alignItems: 'center' }}
      >
        <input
          type="file"
          accept="image/*,.pdf,.txt"
          onChange={handleFileChange}
          ref={fileInputRef}
          style={{
            flex: 1,
            border: isDark ? '1px solid #334155' : '1px solid #ddd',
            borderRadius: 8,
            padding: 6,
            background: isDark ? '#1e293b' : '#f7f9fc',
            color: isDark ? '#f7f9fc' : '#222',
            transition: 'background 0.25s ease, color 0.25s ease'
          }}
          disabled={loading}
        />
        <button
          type="submit"
          disabled={loading || !file}
          style={{
            background: '#2563eb',
            color: '#fff',
            border: 'none',
            borderRadius: 8,
            padding: '8px 18px',
            fontWeight: 600,
            cursor: loading || !file ? 'not-allowed' : 'pointer',
            transition: 'background 0.2s'
          }}
        >
          Send
        </button>
      </form>
      {error && (
        <div style={{ color: 'red', marginTop: 10, textAlign: 'center' }}>{error}</div>
      )}
    </div>
  )
}
